const item = $input.first();
const c = item.json;
const sheetLink = (c['sheet link'] || c['sheet link '] || '').trim();

let sheetGid = '0';
const gidMatch = sheetLink.match(/[#&?]gid=(\d+)/);
if (gidMatch) sheetGid = gidMatch[1];

return [{
  json: {
    channelName: c['channel'] || '',
    sheetLink: sheetLink,
    sheetGid: sheetGid,
    channelId: c['channel id'] || '',
    credential_name: c['credential_name'] || '',
    refresh_token: c['refresh_token'] || '',
    client_id: c['client id'] || c['client_id'] || '',
    secret_id: c['secret id'] || c['secret_id'] || '',
    masterRowNumber: c['row_number'] || '',
    mail: c['mail'] || c['email'] || c['Email'] || ''
  }
}];

const items = $input.all();
const ch = $('Extract Channel Data').first().json;

const pending = items.filter(i => {
  const s = (i.json['Status'] || i.json['status'] || '').toString().trim().toLowerCase();
  return s === 'pending';
});

if (pending.length === 0) {
  return [{ json: { noVideos: true, channelName: ch.channelName, mail: ch.mail, sheetLink: ch.sheetLink, sheetGid: ch.sheetGid } }];
}

return pending.map(i => ({ json: { ...i.json, noVideos: false, channelName: ch.channelName, sheetLink: ch.sheetLink, sheetGid: ch.sheetGid, channelId: ch.channelId, credential_name: ch.credential_name, refresh_token: ch.refresh_token, client_id: ch.client_id, secret_id: ch.secret_id, mail: ch.mail } }));

const item = $input.first();

const driveUrl = (item.json['URL'] || item.json['url'] || '').trim();

let fileId = '';
const match = driveUrl.match(/\/d\/([a-zA-Z0-9_-]+)/);
if (match) fileId = match[1];

if (!fileId) throw new Error('File ID nahi mila: ' + driveUrl);

const title = (item.json['Title '] || item.json['Title'] || '')  // 👈 space wala pehle
  .replace(/[<>]/g, '')
  .trim()
  .substring(0, 100);

const description = (item.json['Description'] || item.json['description'] || '')
  .replace(/[<>]/g, '')
  .trim()
  .substring(0, 4990);

if (!title) throw new Error('Title empty hai. Value: ' + JSON.stringify(item.json['Title ']));

return [{
  json: {
    ...item.json,
    driveUrl,
    fileId,
    title,
    description
  }
}];

const item = $input.first();
const meta = $('Extract Video Info').first().json;
return [{ json: { ...meta }, binary: item.binary }];

const tokenResp = $input.first().json;
const access_token = tokenResp.access_token;
if (!access_token) throw new Error('No access_token received: ' + JSON.stringify(tokenResp));

const video = $('Attach Meta To Binary').first();
return [{ json: { ...video.json, access_token }, binary: video.binary }];

