const resp = $input.first().json;
const uploadUrl = resp.headers?.location || resp.headers?.Location;
if (!uploadUrl) throw new Error('Upload URL nahi mili: ' + JSON.stringify(resp.headers));

const videoItem = $('Prep Token').first();
return [{ json: { ...videoItem.json, uploadUrl }, binary: videoItem.binary }];

const resp = $input.first().json;
const meta = $('Extract Upload URL').first().json;
const videoId = resp.id || '';
const videoLink = videoId ? 'https://youtu.be/' + videoId : '';

const now = new Date();
const dd = String(now.getUTCDate() + 5/24 | 0).padStart(2,'0');
const pkt = new Date(Date.now() + 5*60*60*1000);
const dateStr = String(pkt.getUTCDate()).padStart(2,'0') + '/' + String(pkt.getUTCMonth()+1).padStart(2,'0') + '/' + pkt.getUTCFullYear();

return [{
  json: {
    ...meta,
    youtubeVideoId: videoId,
    youtubeLink: videoLink,
    uploadSuccess: true,
    uploadDate: dateStr
  }
}];

const item = $input.first();
const meta = $('Extract Video Info').first().json;
return [{
  json: {
    row_number: meta.row_number || '',
    URL: meta.URL || meta.url || '',
    sheetLink: meta.sheetLink || '',
    sheetGid: meta.sheetGid || '0',
    channelName: meta.channelName || '',
    errorMessage: 'Google Drive download failed',
    hasError: true
  }
}];

const item = $input.first();
const video = $('Attach Meta To Binary').first().json;
return [{
  json: {
    URL: video.URL || video.url || '',
    sheetLink: video.sheetLink || '',
    sheetGid: video.sheetGid || '0',
    channelName: video.channelName || '',
    errorMessage: 'Auth token refresh failed: 401 unauthorized',
    hasError: true
  }
}];

const item = $input.first();
const errorMsg = item.json.error?.message || item.json.message || JSON.stringify(item.json.error) || '';
const isQuota = errorMsg.toLowerCase().includes('quotaexceeded') || errorMsg.toLowerCase().includes('quota');

const video = $('Prep Token').first().json;
return [{
  json: {
    URL: video.URL || video.url || '',
    sheetLink: video.sheetLink || '',
    sheetGid: video.sheetGid || '0',
    channelName: video.channelName || '',
    title: video.title || '',
    mail: video.mail || '',
    isQuotaError: isQuota,
    errorMessage: isQuota ? 'YouTube API Quota Exceeded' : ('Upload Init Failed: ' + errorMsg)
  }
}];
